import re, glob
cited = set()
for f in glob.glob('*.tex'):
    with open(f) as fh:
        text = fh.read()
    for m in re.finditer(r'\\\\cite[tp]?\{([^}]+)\}', text):
        for key in m.group(1).split(','):
            cited.add(key.strip())
bib_keys = set()
with open('references.bib') as fh:
    for m in re.finditer(r'@\w+\{([^,]+),', fh.read()):
        bib_keys.add(m.group(1).strip())
orphans = bib_keys - cited
missing = cited - bib_keys
print(f'Cited: {len(cited)}, Bib: {len(bib_keys)}, Orphans: {len(orphans)}, Missing: {len(missing)}')
if orphans: print('Orphans:', sorted(orphans))
if missing: print('Missing:', sorted(missing))
"

